/* ===================== BÀI 22 · CALL/RET near và far ===================== */
/* Bài 22 · CALL/RET near và far (AMTS-EMB-002-M06-L02, X86-022) — sinh bởi tools/author/mpu8086/l22.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8086 và bài tập chấm tự động (đề, code mẫu, test). Lời giải không nằm ở đây. */
const P22=[{"label": "Ví dụ: CALL gần và địa chỉ trả về", "code": "; Ví dụ 1: CALL gần cất địa chỉ trả về, RET lấy lại\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     DL, 'A'\n        CALL    inkt                    ; cất 0005h (IP lệnh sau) rồi nhảy\n        MOV     DL, 'B'\n        CALL    inkt                    ; lần này cất 000Ah\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\ninkt    PROC    NEAR                    ; in ký tự trong DL\n        MOV     AH, 02H\n        INT     21H\n        RET                             ; lấy địa chỉ trả về vào IP\ninkt    ENDP\n        END     MAIN\n", "input": "", "note": "Bấm Từng bước tới CALL inkt và nhìn phần Ngăn xếp: SP giảm 2 và word 0005h (IP của MOV DL, 'B') được cất; IP nhảy tới 000Fh. RET lấy 0005h vào IP. Lần gọi thứ hai cất 000Ah. Hai lệnh CALL cùng đích nhưng mã máy E8 0A 00 và E8 05 00 khác nhau vì độ dời tính từ lệnh sau CALL. Đoán trước: ngay sau CALL thứ hai, word ở đỉnh ngăn xếp bằng bao nhiêu? Đáp án 000Ah."}, {"label": "Ví dụ: thủ tục xa ở đoạn mã khác", "code": "; Ví dụ 2: thủ tục xa nằm ở một đoạn mã khác\nDULIEU  SEGMENT\np       DD      inxa                    ; con trỏ xa: độ lệch, đoạn\ntb      DB      'Xa$'\nDULIEU  ENDS\nNGANXEP SEGMENT STACK\n        DW      64 DUP(?)\nNGANXEP ENDS\nCHINH   SEGMENT\n        ASSUME  CS:CHINH, DS:DULIEU, SS:NGANXEP\nMAIN    PROC\n        MOV     AX, DULIEU\n        MOV     DS, AX\n        CALL    inxa                    ; 9A: cất CS rồi IP\n        CALL    p                       ; FF 1E: gọi xa qua con trỏ\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\nCHINH   ENDS\nTHUVIEN SEGMENT\n        ASSUME  CS:THUVIEN\ninxa    PROC    FAR\n        MOV     DX, OFFSET tb\n        MOV     AH, 09H\n        INT     21H\n        RET                             ; trong PROC FAR: RETF (CB)\ninxa    ENDP\nTHUVIEN ENDS\n        END     MAIN\n", "input": "", "note": "Chương trình tự khai báo bốn đoạn bằng SEGMENT. CALL inxa (9A, 28 chu kỳ) cất CS = 0711h rồi IP; CS đổi sang 0713h (đoạn THUVIEN). RET trong PROC FAR được dịch thành RETF (CB, 18 chu kỳ). CALL p gọi xa qua con trỏ DD (37 + 6 = 43 chu kỳ). Màn hình in XaXa. Đoán trước: ngay sau CALL inxa, CS bằng bao nhiêu? Đáp án 0713h (giả định bố trí của trình mô phỏng)."}, {"label": "Ví dụ: CALL gián tiếp qua bảng thủ tục", "code": "; Ví dụ 3: CALL gián tiếp qua bảng địa chỉ thủ tục\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nbang    DW      in0, in1, in2           ; độ lệch của 3 thủ tục\nt0      DB      'Khong$'\nt1      DB      'Mot$'\nt2      DB      'Hai$'\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H\n        INT     21H                     ; AL = '0', '1' hoặc '2'\n        SUB     AL, '0'\n        MOV     BL, AL\n        MOV     BH, 0\n        SHL     BX, 1                   ; mỗi ô bảng 2 byte\n        CALL    bang[BX]                ; IP = bang[BX]\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\nin0     PROC    NEAR\n        MOV     DX, OFFSET t0\n        MOV     AH, 09H\n        INT     21H\n        RET\nin0     ENDP\nin1     PROC    NEAR\n        MOV     DX, OFFSET t1\n        MOV     AH, 09H\n        INT     21H\n        RET\nin1     ENDP\nin2     PROC    NEAR\n        MOV     DX, OFFSET t2\n        MOV     AH, 09H\n        INT     21H\n        RET\nin2     ENDP\n        END     MAIN\n", "input": "2", "note": "Dữ liệu nhập 2. Phím '2' → AL = 2 → BX = 4 sau SHL BX, 1. CALL bang[BX] (FF 97, 21 + 9 = 30 chu kỳ) đọc word ở bang + 4 = độ lệch của in2, rồi gọi như CALL gần. Xem bảng bang trong phần Bộ nhớ: 001Ah, 0022h, 002Ah. Màn hình in Hai. Đoán trước: trước CALL bang[BX], BX bằng bao nhiêu? Đáp án 0004h."}, {"label": "Lỗi: PUSH trong thủ tục, quên POP", "code": "; Ví dụ 4 (lỗi): PUSH trong thủ tục nhưng quên POP\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     DL, 'A'\n        CALL    inkt\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\ninkt    PROC    NEAR\n        PUSH    BX                      ; cất BX (đang là 0)\n        MOV     BX, 1                   ; dùng BX vào việc khác\n        MOV     AH, 02H\n        INT     21H\n        RET                             ; SAI: thiếu POP BX, RET lấy 0000h\ninkt    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi cố ý: inkt PUSH BX nhưng không POP. Khi RET, đỉnh ngăn xếp là BX cũ (0000h) chứ không phải 0005h, nên IP = 0000h và chương trình chạy lại từ đầu. Lần sau BX đã là 1: RET về 0001h, giữa lệnh MOV DL, 'A', byte 41h được giải mã thành INC CX. Chữ A được in mãi tới khi trình mô phỏng dừng. Sửa: thêm POP BX ngay trước RET. Đoán trước: lần RET đầu tiên, IP nhận giá trị nào? Đáp án 0000h."}, {"label": "Lỗi: gọi gần một thủ tục xa", "code": "; Ví dụ 5 (lỗi): gọi gần một thủ tục xa\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     DL, 'A'\n        CALL    NEAR PTR inxa           ; chỉ cất IP (E8)\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\ninxa    PROC    FAR\n        MOV     AH, 02H\n        INT     21H\n        RET                             ; RETF lấy IP rồi lấy thêm CS\ninxa    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi cố ý: CALL NEAR PTR inxa chỉ cất IP (E8, 3 byte), nhưng inxa là PROC FAR nên RET là RETF: lấy IP = 0005h rồi lấy thêm word phía trên làm CS. Word đó nằm ngay trên đáy ngăn xếp, ngoài vùng .STACK; trên trình mô phỏng nó là 0000h (bộ nhớ chưa dùng là 0, trên máy thật là giá trị bất kỳ) nên CPU chạy ở 0000:0005, giữa bảng vectơ ngắt, tới khi gặp mã FEh không hợp lệ. Sửa: CALL inxa (để trình dịch sinh CALL xa) hoặc khai báo inxa PROC NEAR. Đoán trước: sau RETF, CS bằng bao nhiêu? Đáp án 0000h."}, {"label": "Lỗi: quên RET, chạy lọt sang thủ tục sau", "code": "; Ví dụ 6 (lỗi): quên RET, chạy lọt sang thủ tục sau\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        CALL    inA\n        CALL    inB\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\ninA     PROC    NEAR\n        MOV     DL, 'A'\n        MOV     AH, 02H\n        INT     21H                     ; SAI: thiếu RET ở đây\ninA     ENDP\ninB     PROC    NEAR\n        MOV     DL, 'B'\n        MOV     AH, 02H\n        INT     21H\n        RET\ninB     ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi cố ý: inA thiếu RET. ENDP không sinh lệnh nào nên sau INT 21h CPU chạy tiếp các lệnh của inB, in thêm B rồi gặp RET của inB và quay về MAIN. Sau đó MAIN gọi inB: màn hình in ABB thay vì AB. Sửa: thêm RET cuối inA. Đoán trước: sau lần INT 21h đầu tiên, lệnh tiếp theo là gì? Đáp án MOV DL, 'B' của inB."}, {"label": "Ví dụ: giá của CALL/RET, JMP cho lời gọi cuối", "code": "; Ví dụ 7: giá của CALL/RET; JMP thay lời gọi cuối\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     DL, 'x'\n        CALL    hai                     ; in DL hai lần\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\ninkt    PROC    NEAR\n        MOV     AH, 02H\n        INT     21H\n        RET\ninkt    ENDP\nhai     PROC    NEAR\n        CALL    inkt                    ; CALL 19 + RET 8 chu kỳ\n        JMP     inkt                    ; lời gọi cuối: chỉ JMP 15,\nhai     ENDP                            ; RET của inkt về thẳng MAIN\n        END     MAIN\n", "input": "", "note": "Thủ tục hai gọi inkt hai lần. Lần đầu là CALL (19) + RET (8). Lần cuối dùng JMP inkt (EB, 15 chu kỳ): không cất gì thêm, nên RET của inkt lấy 0005h và về thẳng MAIN. Xem phần Ngăn xếp: chỉ có tối đa 2 word. Màn hình in xx. Đoán trước: khi RET của inkt chạy lần thứ hai, IP nhận giá trị nào? Đáp án 0005h."}];
const sim22=makeX86Sim(document.getElementById("x86-l22"),{id:"s22",presets:P22,file:"BAI22.ASM"});
makeX86Ex(document.getElementById("ex-l22"),sim22,[{"t": "In mã ASCII hệ 16", "d": "Đọc một phím bằng INT 21h hàm 08h rồi in mã ASCII của phím đó bằng đúng 2 chữ số hệ 16, chữ hoa, không có chữ h (ví dụ phím A in 41, phím z in 7A). Dùng thủ tục gần inhex có sẵn trong code mẫu (vào AL = 0..15, in một chữ số; làm hỏng AX, DL), gọi hai lần: nửa cao trước, nửa thấp sau. Kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 1: in mã ASCII của một phím bằng 2 chữ số hệ 16\n; Thủ tục inhex đã đúng. Code mẫu mới in nửa thấp;\n; hãy in nửa cao trước rồi nửa thấp (gọi inhex 2 lần).\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AH, 08H\n        INT     21H                     ; AL = mã phím\n        AND     AL, 0FH                 ; nửa thấp\n        CALL    inhex\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n; inhex: vào AL = 0..15, in một chữ số hệ 16.\n; Làm hỏng AX, DL. Giữ nguyên BX, CX.\ninhex   PROC    NEAR\n        CMP     AL, 10\n        JB      so\n        ADD     AL, 7                   ; 10..15 → 'A'..'F' ('A' - '0' - 10 = 7)\nso:\n        ADD     AL, '0'\n        MOV     DL, AL\n        MOV     AH, 02H\n        INT     21H\n        RET\ninhex   ENDP\n        END     MAIN\n", "tests": [{"in": "A", "out": "41"}, {"in": "z", "out": "7A"}, {"in": "0", "out": "30"}, {"in": " ", "out": "20"}, {"in": "~", "out": "7E"}, {"in": "J", "out": "4A"}, {"in": "?", "out": "3F"}]}, {"t": "Bảng thủ tục theo phím", "d": "Đọc hai phím bằng INT 21h hàm 08h: phím lệnh rồi một chữ thường c. Phím lệnh 0 in c; 1 in c hai lần; 2 in chữ hoa của c; 3 in [c] (c trong ngoặc vuông). Phím lệnh khác 0–3 thì in ? và không gọi thủ tục nào. Chọn thủ tục bằng bảng địa chỉ và CALL gián tiếp, như code mẫu. Kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 2: chọn thủ tục theo phím qua bảng địa chỉ\n; Code mẫu mới có lệnh 0 và 1. Hãy viết thêm p2, p3,\n; thêm chúng vào bảng và sửa phép kiểm phạm vi.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nbang    DW      p0, p1                  ; độ lệch các thủ tục\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H\n        INT     21H                     ; phím lệnh '0'..'3'\n        MOV     BL, AL\n        MOV     AH, 08H\n        INT     21H\n        MOV     DL, AL                  ; DL = ký tự cần in\n        SUB     BL, '0'\n        CMP     BL, 1                   ; ngoài bảng thì in '?'\n        JA      sai\n        MOV     BH, 0\n        SHL     BX, 1                   ; mỗi ô bảng 2 byte\n        CALL    bang[BX]\n        JMP     het\nsai:\n        MOV     DL, '?'\n        MOV     AH, 02H\n        INT     21H\nhet:\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\np0      PROC    NEAR                    ; in DL\n        MOV     AH, 02H\n        INT     21H\n        RET\np0      ENDP\np1      PROC    NEAR                    ; in DL hai lần\n        MOV     AH, 02H\n        INT     21H\n        INT     21H\n        RET\np1      ENDP\n        END     MAIN\n", "tests": [{"in": "0a", "out": "a"}, {"in": "1b", "out": "bb"}, {"in": "2c", "out": "C"}, {"in": "3d", "out": "[d]"}, {"in": "4e", "out": "?"}, {"in": "/x", "out": "?"}, {"in": "2z", "out": "Z"}, {"in": "3q", "out": "[q]"}]}, {"t": "Gọi gần thay gọi xa", "d": "Đọc lần lượt 4 phím chữ số 0–9 và ghi tổng giá trị của chúng (0–36) vào biến tong (1 byte). Không in gì; kết thúc bằng INT 21h hàm 4Ch. Code mẫu đúng kết quả nhưng gọi thủ tục xa docso trong một chương trình chỉ có một đoạn mã. Viết lại để đạt cả giới hạn chu kỳ và byte mã.", "start": "; Bài tập 3: cộng 4 chữ số, thủ tục đọc số nhanh hơn\n; Bản này đúng nhưng docso là thủ tục XA: mỗi lần gọi\n; tốn CALL xa 28 + RETF 18 chu kỳ. Chương trình chỉ có\n; một đoạn mã. Hãy viết lại cho đạt giới hạn.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ntong    DB      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        XOR     BL, BL                  ; tổng\n        MOV     CX, 4\nlap:\n        CALL    docso                   ; AL = giá trị chữ số\n        ADD     BL, AL\n        LOOP    lap\n        MOV     tong, BL\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n; docso: đọc một phím '0'..'9', trả AL = 0..9. Hỏng AH.\ndocso   PROC    FAR\n        MOV     AH, 08H\n        INT     21H\n        SUB     AL, '0'\n        RET\ndocso   ENDP\n        END     MAIN\n", "tests": [{"in": "1234", "mem": [{"at": "tong", "bytes": [10]}]}, {"in": "0000", "mem": [{"at": "tong", "bytes": [0]}]}, {"in": "9999", "mem": [{"at": "tong", "bytes": [36]}]}, {"in": "9000", "mem": [{"at": "tong", "bytes": [9]}]}, {"in": "0009", "mem": [{"at": "tong", "bytes": [9]}]}, {"in": "5371", "mem": [{"at": "tong", "bytes": [16]}]}], "perf": {"cycles": 520, "bytes": 36}}]);

makeQuiz("quiz22","score22",[{"q": "CALL gần ở độ lệch 0020h, thủ tục ở 0012h. Mã máy của lệnh CALL là gì?", "o": ["<code>E8 12 00<\/code> (độ lệch của thủ tục)", "<code>E8 F2 FF<\/code> (độ dời 0012h − 0020h = −0Eh)", "<code>9A 12 00<\/code> (CALL gần dùng địa chỉ tuyệt đối)", "<code>E8 EF FF<\/code> (độ dời 0012h − 0023h = −11h)"], "a": 3, "e": "Độ dời của E8 tính từ lệnh sau CALL: 0020h + 3 = 0023h, 0012h − 0023h = −11h = FFEFh, ghi byte thấp trước: EF FF. Tính từ chính lệnh CALL là nhầm phổ biến; 9A là CALL xa, mang độ lệch và đoạn."}, {"q": "Đoạn sau chạy với SP = 0100h ngay trước CALL. Khi CPU đang ở lệnh đầu của <code>f<\/code>, SP và word ở đỉnh ngăn xếp là gì?<pre class=\"mp-asm\">0710:0030  CALL FAR PTR f   ; 5 byte\n0710:0035  MOV AX, 4C00h<\/pre>", "o": ["SP = 00FCh, đỉnh là 0035h (IP), dưới nó là 0710h (CS)", "SP = 00FEh, đỉnh là 0035h, CS không được cất", "SP = 00FCh, đỉnh là 0710h (CS), dưới nó là 0035h (IP)", "SP = 00FCh, đỉnh là 0030h (địa chỉ của chính lệnh CALL)"], "a": 0, "e": "CALL xa cất CS trước rồi IP, nên IP (0035h, lệnh sau CALL) nằm ở đỉnh, CS ở 00FEh; SP giảm 4. Chỉ cất IP là lời gọi gần."}, {"q": "Thủ tục sau được gọi bằng <code>CALL inkt<\/code>. Lỗi là gì?<pre class=\"mp-asm\">inkt    PROC    NEAR\n        PUSH    DX\n        MOV     AH, 02H\n        INT     21H\n        RET\ninkt    ENDP<\/pre>", "o": ["Thiếu POP DX: RET lấy giá trị DX làm địa chỉ trả về", "Thiếu POP DX nên DX bị đổi sau khi thủ tục trả về", "PUSH DX làm SP tăng 2 nên RET lấy nhầm word phía trên", "Không có lỗi: RET tự bỏ qua các word đã PUSH trong thủ tục"], "a": 0, "e": "RET chỉ lấy word ở đỉnh ngăn xếp, lúc này là DX đã PUSH. CPU nhảy tới độ lệch bằng giá trị DX (Ví dụ 4). PUSH làm SP giảm chứ không tăng; RET không biết thủ tục đã PUSH gì."}, {"q": "Chương trình <code>.MODEL SMALL<\/code> chỉ có một đoạn mã, gọi thủ tục <code>docso<\/code> 1000 lần trong vòng lặp. Đổi <code>docso PROC FAR<\/code> thành <code>PROC NEAR<\/code> bớt được bao nhiêu chu kỳ?", "o": ["9 000 chu kỳ (mỗi lời gọi: 28 − 19)", "10 000 chu kỳ (mỗi lời gọi: 18 − 8)", "19 000 chu kỳ (mỗi lời gọi: 46 − 27)", "Không bớt được, vì CALL gần và xa cùng chạy 19 chu kỳ"], "a": 2, "e": "Xa: CALL 28 + RETF 18 = 46; gần: CALL 19 + RET 8 = 27; mỗi lời gọi bớt 19 chu kỳ (bài tập 3). Hai lựa chọn giữa chỉ tính một nửa của cặp CALL/RET."}, {"q": "<code>bang DW p0, p1, p2<\/code>, phím đọc vào AL. Đoạn nào gọi đúng thủ tục thứ AL − '0' và chặn phím ngoài 0–2?", "o": ["<code>SUB AL,'0'<\/code> / <code>CMP AL,2<\/code> / <code>JG sai<\/code> / <code>MOV BL,AL<\/code> / <code>MOV BH,0<\/code> / <code>SHL BX,1<\/code> / <code>CALL bang[BX]<\/code>", "<code>SUB AL,'0'<\/code> / <code>CMP AL,2<\/code> / <code>JA sai<\/code> / <code>MOV BL,AL<\/code> / <code>MOV BH,0<\/code> / <code>CALL bang[BX]<\/code>", "<code>SUB AL,'0'<\/code> / <code>CMP AL,2<\/code> / <code>JA sai<\/code> / <code>MOV BL,AL<\/code> / <code>MOV BH,0<\/code> / <code>SHL BX,1<\/code> / <code>CALL bang[BX]<\/code>", "<code>SUB AL,'0'<\/code> / <code>CMP AL,2<\/code> / <code>JA sai<\/code> / <code>MOV BL,AL<\/code> / <code>SHL BX,1<\/code> / <code>CALL bang[BX]<\/code>"], "a": 2, "e": "Cần cả ba: so sánh không dấu (JA chặn cả phím nhỏ hơn '0' vì hiệu âm là số không dấu lớn; JG coi FFh là −1 nên để lọt), BH = 0, và nhân 2 vì mỗi ô 2 byte."}]);

